    if not me.can_drive:
        return (0.0, 0.0)

    # Bearing to the enemy (degrees, -180 .. 180, positive = left)
    bearing = bearing_to(enemy.x, enemy.y)

    # Simple proportional steering
    if abs(bearing) < 10:
        left = right = 1.0
    elif bearing > 0:
        left = 0.5
        right = 1.0
    else:
        left = 1.0
        right = 0.5

    # Clamp to allowed range
    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)


