        elif b < -10:
            side = -1
        me.memory["side"] = side
        if d > 2.0:
            desired = 0
        else:
            desired = 25 * side
    be = b - desired
    if abs(be) > 90:
        if be > 0:
            lt = -0.4
            rt = 1.0
        else:
            lt = 1.0
            rt = -0.4
    else:
        turn = be / 45.0
        if turn > 1:
            turn = 1
        if turn < -1:
            turn = -1
        lt = 1.0 - 0.5 * turn
        rt = 1.0 + 0.5 * turn
        if lt < 0:
            lt = 0
        if rt > 1:
            rt = 1
        if lt > 1:
            lt = 1
    if d < 0.9:
        lt = lt * 0.45
        rt = rt * 0.45
    elif d < 1.4:
        lt = lt * 0.7
        rt = rt * 0.7
    tmax = me.drive_left_temperature
    if me.drive_right_temperature > tmax:
        tmax = me.drive_right_temperature
    if tmax > 140:
