def drive(me, enemy, arena):
    # If we cannot drive, stay still
    if not me.can_drive:
        return (0.0, 0.0)

    # Simple proportional steering towards the enemy
    bearing = bearing_to(enemy.x, enemy.y)  # degrees, positive = left

    # If roughly facing the enemy, go full forward
    if abs(bearing) < 5:
        left = right = 1.0
    # Turn left or right by reducing opposite side throttle
    elif bearing > 0:
        left = 0.5
        right = 1.0
    else:
        left = 1.0
        right = 0.5

    # Clamp throttle values
    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)


