        b = bearing_to(tx, ty)
        d = distance_to(tx, ty)
        if d > 3.0:
            full = 1.0
        elif d > 2.0:
            full = 0.95
        elif d > 1.2:
            full = 0.85
        elif d > 0.7:
            full = 0.65
        else:
            full = 0.5

    if b > 180:
        b = b - 360
    if b < -180:
        b = b + 360

    if abs(b) > 95:
        if b > 0:
            lt = -0.5
            rt = 1.0
        else:
            lt = 1.0
            rt = -0.5
    else:
        turn = b / 35.0
        if turn > 1:
            turn = 1
        if turn < -1:
            turn = -1
        lt = full - 0.5 * turn
        rt = full + 0.5 * turn
        if lt < 0:
            lt = 0
        if rt < 0:
            rt = 0
        if lt > 1:
            lt = 1
        if rt > 1:
            rt = 1

    tmax = me.drive_left_temperature
    if me.drive_right_temperature > tmax:
